		// it: the new agent's first report lands before they return (ADR
		// 26-11-15-602 §1).
		sandbox.ReportAgentStarted(ctx, time.Now(), sandbox.AgentStartInPlace)
	}
	box, err := poolruntime.ProvisionBox(agentCtx, guest, maker, placement)
	if err != nil {
